-- v1.4: owner-scoped customers, projects, tasks, costs and receipts. Non-destructive.
CREATE TABLE IF NOT EXISTS public.helio_customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id),exhibitor_id uuid REFERENCES public.exhibitors(id),company_name text NOT NULL,contact_name text,email text,phone text,notes text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,id),UNIQUE(owner_id,exhibitor_id),FOREIGN KEY(owner_id,exhibitor_id) REFERENCES public.exhibitors(owner_id,id));
CREATE TABLE IF NOT EXISTS public.helio_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id),customer_id uuid NOT NULL,opportunity_id uuid,project_name text NOT NULL,status text NOT NULL DEFAULT 'planning' CHECK(status IN ('planning','active','on_hold','completed','cancelled')),start_on date,due_on date,contract_value numeric(14,2) NOT NULL DEFAULT 0 CHECK(contract_value>=0),estimated_cost numeric(14,2) NOT NULL DEFAULT 0 CHECK(estimated_cost>=0),notes text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,id),FOREIGN KEY(owner_id,customer_id) REFERENCES public.helio_customers(owner_id,id),FOREIGN KEY(owner_id,opportunity_id) REFERENCES public.helio_opportunities(owner_id,id));
CREATE TABLE IF NOT EXISTS public.helio_project_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id),project_id uuid NOT NULL,title text NOT NULL,assignee text,due_on date,status text NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','in_progress','done')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(owner_id,project_id) REFERENCES public.helio_projects(owner_id,id));
CREATE TABLE IF NOT EXISTS public.helio_project_costs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id),project_id uuid NOT NULL,description text NOT NULL,amount numeric(14,2) NOT NULL CHECK(amount>=0),incurred_on date NOT NULL DEFAULT CURRENT_DATE,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(owner_id,project_id) REFERENCES public.helio_projects(owner_id,id));
CREATE TABLE IF NOT EXISTS public.helio_project_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id),project_id uuid NOT NULL,amount numeric(14,2) NOT NULL CHECK(amount>0),received_on date NOT NULL DEFAULT CURRENT_DATE,method text NOT NULL DEFAULT 'bank_transfer',reference text,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(owner_id,project_id) REFERENCES public.helio_projects(owner_id,id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['helio_customers','helio_projects','helio_project_tasks','helio_project_costs','helio_project_payments'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS helio_owner_select ON public.%I',t); EXECUTE format('DROP POLICY IF EXISTS helio_owner_insert ON public.%I',t); EXECUTE format('DROP POLICY IF EXISTS helio_owner_update ON public.%I',t); EXECUTE format('DROP POLICY IF EXISTS helio_owner_delete ON public.%I',t); EXECUTE format('CREATE POLICY helio_owner_select ON public.%I FOR SELECT TO authenticated USING (owner_id=(SELECT auth.uid()))',t); EXECUTE format('CREATE POLICY helio_owner_insert ON public.%I FOR INSERT TO authenticated WITH CHECK (owner_id=(SELECT auth.uid()))',t); EXECUTE format('CREATE POLICY helio_owner_update ON public.%I FOR UPDATE TO authenticated USING (owner_id=(SELECT auth.uid())) WITH CHECK (owner_id=(SELECT auth.uid()))',t); EXECUTE format('CREATE POLICY helio_owner_delete ON public.%I FOR DELETE TO authenticated USING (owner_id=(SELECT auth.uid()))',t); END LOOP; END $$;
NOTIFY pgrst,'reload schema';
